import re, pathlib

def add_none_arg(text, fname):
    out = []
    i = 0
    count = 0
    needle = fname + "("
    while True:
        j = text.find(needle, i)
        if j == -1:
            out.append(text[i:])
            break
        # skip the definition
        if text[max(0, j-4):j] == "fn ":
            out.append(text[i:j+len(needle)])
            i = j + len(needle)
            continue
        # find matching close paren, tracking nesting and strings
        k = j + len(needle)
        depth = 1
        in_str = False
        while k < len(text) and depth:
            c = text[k]
            if in_str:
                if c == '\\':
                    k += 2
                    continue
                if c == '"':
                    in_str = False
            elif c == '"':
                in_str = True
            elif c in "([{":
                depth += 1
            elif c in ")]}":
                depth -= 1
            k += 1
        call = text[j:k]
        # count top-level commas in the arg list
        inner = call[len(needle):-1]
        d = 0
        commas = 0
        s = False
        for c in inner:
            if s:
                if c == '"':
                    s = False
            elif c == '"':
                s = True
            elif c in "([{":
                d += 1
            elif c in ")]}":
                d -= 1
            elif c == "," and d == 0:
                commas += 1
        if commas == 2:
            out.append(text[i:j] + call[:-1] + ", None)")
            count += 1
        else:
            out.append(text[i:k])
        i = k
    return "".join(out), count

for path in ["src/discover.rs", "src/runner.rs"]:
    p = pathlib.Path(path)
    t = p.read_text()
    nt, n = add_none_arg(t, "select_artists")
    p.write_text(nt)
    print(f"{path}: updated {n} call site(s)")
